#!/usr/bin/env python3
"""Minimal VT parser rendering an 80x24 (configurable) screen from pty bytes."""
import re, sys

def render(data: bytes, rows=24, cols=80):
    grid = [[' ']*cols for _ in range(rows)]
    r = c = 0
    i = 0
    n = len(data)
    saved = (0,0)
    while i < n:
        b = data[i]
        if b == 0x1b:
            # escape sequence
            m = re.match(rb'\x1b\[([0-9;?]*)([a-zA-Z@`~])', data[i:])
            if m:
                params = m.group(1).decode()
                cmd = chr(m.group(2)[0])
                parts = params.lstrip('?').split(';') if params else []
                nums = [int(p) if p.isdigit() else 0 for p in parts]
                def num(k, d): return nums[k] if k < len(nums) and nums[k] else d
                if cmd == 'H' or cmd == 'f':
                    r = min(max(num(0,1)-1,0), rows-1); c = min(max(num(1,1)-1,0), cols-1)
                elif cmd == 'A': r = max(r - num(0,1), 0)
                elif cmd == 'B': r = min(r + num(0,1), rows-1)
                elif cmd == 'C': c = min(c + num(0,1), cols-1)
                elif cmd == 'D': c = max(c - num(0,1), 0)
                elif cmd == 'G': c = min(max(num(0,1)-1,0), cols-1)
                elif cmd == 'd': r = min(max(num(0,1)-1,0), rows-1)
                elif cmd == 'J':
                    if not nums or nums[0] == 0:
                        for rr in range(r, rows):
                            start = c if rr == r else 0
                            for cc in range(start, cols): grid[rr][cc] = ' '
                    elif nums[0] == 2:
                        grid = [[' ']*cols for _ in range(rows)]
                elif cmd == 'K':
                    if not nums or nums[0] == 0:
                        for cc in range(c, cols): grid[r][cc] = ' '
                elif cmd == 's': saved = (r,c)
                elif cmd == 'u': r,c = saved
                i += m.end()
                continue
            m2 = re.match(rb'\x1b\][^\x07\x1b]*(\x07|\x1b\\)', data[i:])
            if m2:
                i += m2.end(); continue
            m3 = re.match(rb'\x1b[()][0-9A-B]', data[i:])
            if m3:
                i += m3.end(); continue
            m4 = re.match(rb'\x1b[=>M78]', data[i:])
            if m4:
                if chr(m4.group(0)[1]) == '7': saved = (r,c)
                elif chr(m4.group(0)[1]) == '8': r,c = saved
                i += m4.end(); continue
            i += 2
            continue
        if b == 0x0d: c = 0; i += 1; continue
        if b == 0x0a: r = min(r+1, rows-1); i += 1; continue
        if b == 0x08: c = max(c-1,0); i += 1; continue
        if b == 0x09: c = min((c//8+1)*8, cols-1); i += 1; continue
        if b < 0x20 or b == 0x7f: i += 1; continue
        # utf-8 char
        try:
            ch = data[i:i+4].decode('utf-8')[0]
            clen = len(ch.encode('utf-8'))
        except Exception:
            i += 1; continue
        if 0 <= r < rows and 0 <= c < cols:
            grid[r][c] = ch
        c += 1
        i += clen
    return '\n'.join(''.join(row) for row in grid)

if __name__ == '__main__':
    data = open(sys.argv[1],'rb').read()
    print(render(data))

