#!/usr/bin/env python3
"""PTY runner that also captures the child exit code."""
import os, pty, sys, time, select, subprocess, fcntl, termios, struct

def run_ec(args, keys_seq=None, env_extra=None, rows=24, cols=80, wait=1.0, final_wait=2.0):
    env = dict(os.environ)
    env["TERM"] = "xterm-256color"
    if env_extra: env.update(env_extra)
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    p = subprocess.Popen(args, stdin=slave, stdout=slave, stderr=slave, env=env, close_fds=True)
    os.close(slave)
    out = b""
    def drain(dur):
        nonlocal out
        end = time.time() + dur
        while time.time() < end:
            r, _, _ = select.select([master], [], [], max(0, end - time.time()))
            if r:
                try: data = os.read(master, 65536)
                except OSError: return False
                if not data: return False
                out += data
            if p.poll() is not None:
                # keep draining until no more data
                r, _, _ = select.select([master], [], [], 0.1)
                if not r: return False
        return True
    drain(wait)
    if keys_seq:
        for k, w in keys_seq:
            os.write(master, k)
            if not drain(w): break
    if p.poll() is None:
        drain(final_wait)
    alive = p.poll() is None
    if alive:
        p.terminate()
        try: p.wait(timeout=2)
        except Exception: p.kill()
    drain(0.2)
    os.close(master)
    return out, p.returncode, alive

if __name__ == '__main__':
    import json
    env = json.loads(os.environ.get('PTY_ENV','{}'))
    keys = [(bytes.fromhex(x), w) for x, w in json.loads(os.environ.get('PTY_KEYS','[]'))]
    out, ec, alive = run_ec(sys.argv[1:], keys_seq=keys, env_extra=env)
    sys.stdout.buffer.write(out)
    sys.stderr.write(f"\n[exit={ec} alive_at_end={alive}]\n")

